// Movimiento básico frame-independent
transform.position += velocity * Time.deltaTime;

// Aceleración: la velocidad cambia con el tiempo
void Update()
{
    velocity += acceleration * Time.deltaTime;
    transform.position += velocity * Time.deltaTime;
}

// Desaceleración con drag (fricción simple)
void Update()
{
    velocity *= Mathf.Pow(drag, Time.deltaTime); // drag entre 0 y 1
    transform.position += velocity * Time.deltaTime;
}

// Predecir posición después de N segundos (fórmula cinemática)
Vector3 futurePos = startPos + velocity * seconds + 0.5f * acceleration * seconds * seconds;

// Lerp para suavizar movimiento (SmoothDamp)
Vector3 current = transform.position;
Vector3 target = destination;

// t = 0 → current, t = 1 → target
Vector3 lerpPos = Vector3.Lerp(current, target, t);

// Uso común: suavizar gradualmente (framerate-independent)
transform.position = Vector3.Lerp(
    transform.position,
    targetPos,
    smoothSpeed * Time.deltaTime  // ojo: no es lineal, es exponencial
);

// Para velocidad constante real: usa MoveTowards
transform.position = Vector3.MoveTowards(
    transform.position,
    targetPos,
    speed * Time.deltaTime  // mueve exactamente speed unidades/segundo
);

